        setmi("topMargin", args[2].type == DalvikType::INT32 ? args[2].int_val : 0);
        setmi("rightMargin", args[3].type == DalvikType::INT32 ? args[3].int_val : 0);
        setmi("bottomMargin", args[4].type == DalvikType::INT32 ? args[4].int_val : 0);
