                    if (child_dim == -1)
                        return 0x40000000 | (parent_size & 0x3FFFFFFF);
                    if (child_dim == -2)
                        return 0x80000000 | (parent_size & 0x3FFFFFFF);
                    return 0x40000000 | (child_dim & 0x3FFFFFFF);
