                std::cerr << "[S109-VG-MEASURE] " << class_name << " obj#"
                          << recv << " spec=" << pw << "x" << ph
                          << " children_measured=" << measured_children
                          << " -> " << n->measured_width << "x"
                          << n->measured_height << std::endl;
