            pav.type = DalvikType::OBJECT_REF;
            pav.object_id = arr_id;
            pav.class_desc = "[Landroid/content/pm/ProviderInfo;";
            pav.int_val = (int64_t)manifest_provider_identity_.size();
            heap_.set_object_field(obj_id, "providers", pav);
