                                       el.name == "PreferenceCategory" ||
                                       el.name == "Preference" ||
                                       el.name == "CheckBoxPreference" ||
                                       el.name == "SwitchPreference" ||
                                       el.name == "ListPreference" ||
                                       el.name == "EditTextPreference" ||
                                       el.name == "RingtonePreference" ||
                                       el.name == "MultiSelectListPreference";
