                        bool boolish = ename.find("CheckBoxPreference") != std::string::npos ||
                                       ename.find("SwitchPreference") != std::string::npos ||
                                       ename.find("TwoStatePreference") != std::string::npos ||
                                       ename.find("TogglePreference") != std::string::npos;
