            (1 << 7) |    // NET_CAPABILITY_NOT_RESTRICTED
            (1 << 8) |    // NET_CAPABILITY_TRUSTED
            (1 << 9) |    // NET_CAPABILITY_NOT_VPN
            (1 << 10) |   // NET_CAPABILITY_VALIDATED
            (1 << 12) |   // NET_CAPABILITY_INTERNET
            (1 << 13);    // NET_CAPABILITY_NOT_METERED
        static const int32_t kTransportBits =
            (1 << 1);     // TRANSPORT_WIFI
