                DalvikValue cb_ret;
                DalvikExecutionResult cb_res;
                bool got_size =
                    try_recursive_invoke(f238_rcls, "size", cb_args, cb_ret,
                                         cb_res, "()I") ||
                    try_recursive_invoke_on_super(
                        f238_rcls, "size", cb_args, cb_ret, cb_res, "()I");
